const sheetState={key:'',query:'',difficulty:'All',status:'All'};
function sheetCount(list){return list.filter(n=>statusOf(n)==='revised').length}
function sheetGroups(topic,subgroup){
  if(topic==='Sorting'){
    const groups=[['Sorting I',notes.filter(n=>n.topic==='Sorting'&&Number(n.id)<=43)],['Sorting II',notes.filter(n=>n.topic==='Sorting'&&Number(n.id)>=44)]];
    return subgroup==='1'?[groups[0]]:subgroup==='2'?[groups[1]]:groups;
  }
  const groups=['Easy','Medium','Hard'].map(d=>[d,notes.filter(n=>n.topic==='Arrays'&&n.difficulty===d)]);
  return subgroup?groups.filter(([d])=>d.toLowerCase()===subgroup):groups;
}
function sheetSource(n){let host='';try{host=new URL(n.link).hostname}catch{}return host.includes('leetcode')?'LeetCode':host.includes('takeuforward')?'TUF':'Source'}
function sheetRow(n){const done=statusOf(n)==='revised',needs=statusOf(n)==='needs';return `<div class="sheet-row ${done?'is-done':''}"><label class="sheet-check-wrap"><input class="sheet-check" type="checkbox" data-id="${n.id}" ${done?'checked':''} aria-label="Mark ${esc(n.title)} as ${done?'not done':'revised'}"><span></span></label><a class="sheet-problem-link" href="${url(n)}"><span class="sheet-problem-title">${esc(n.title)}</span><span class="sheet-problem-pattern">${esc(n.pattern)}</span></a><span class="sheet-row-difficulty">${badge(n)}</span><button type="button" class="sheet-flag ${needs?'active':''}" data-action="flag" data-id="${n.id}" aria-label="${needs?'Remove revision flag':'Flag for revision'}: ${esc(n.title)}" title="${needs?'Remove revision flag':'Flag for revision'}">${needs?'★':'☆'}</button><a class="sheet-source" href="${esc(n.link)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(n.title)} on ${sheetSource(n)}">${sheetSource(n)} ↗</a></div>`}
function sheetSidebar(activeTopic,subgroup){const arrays=notes.filter(n=>n.topic==='Arrays'),sorting=notes.filter(n=>n.topic==='Sorting');return `<aside class="sheet-sidebar" id="sheet-sidebar" aria-label="Sheet sections"><div class="sheet-side-brand"><span class="brand-mark">⌘</span><span>Problem sheet</span><button type="button" class="sheet-close" data-sheet-action="close-sidebar" aria-label="Close sections">×</button></div><p class="sheet-side-label">YOUR NOTES</p><a class="sheet-side-topic ${activeTopic==='Arrays'?'selected':''}" href="#/topics/arrays"><span class="sheet-side-number">01</span><span>Arrays</span><small>${sheetCount(arrays)}/${arrays.length}</small></a><div class="sheet-side-children"><a class="${activeTopic==='Arrays'&&subgroup==='easy'?'selected':''}" href="#/topics/arrays/easy">Easy <small>${sheetCount(arrays.filter(n=>n.difficulty==='Easy'))}/14</small></a><a class="${activeTopic==='Arrays'&&subgroup==='medium'?'selected':''}" href="#/topics/arrays/medium">Medium <small>${sheetCount(arrays.filter(n=>n.difficulty==='Medium'))}/14</small></a><a class="${activeTopic==='Arrays'&&subgroup==='hard'?'selected':''}" href="#/topics/arrays/hard">Hard <small>${sheetCount(arrays.filter(n=>n.difficulty==='Hard'))}/12</small></a></div><a class="sheet-side-topic ${activeTopic==='Sorting'?'selected':''}" href="#/topics/sorting"><span class="sheet-side-number">02</span><span>Sorting</span><small>${sheetCount(sorting)}/${sorting.length}</small></a><div class="sheet-side-children"><a class="${activeTopic==='Sorting'&&subgroup==='1'?'selected':''}" href="#/topics/sorting/1">Sorting I <small>${sheetCount(sorting.filter(n=>Number(n.id)<=43))}/3</small></a><a class="${activeTopic==='Sorting'&&subgroup==='2'?'selected':''}" href="#/topics/sorting/2">Sorting II <small>${sheetCount(sorting.filter(n=>Number(n.id)>=44))}/4</small></a></div><div class="sheet-side-bottom"><a href="#/patterns">Browse patterns ↗</a><a href="#/revise">Revision queue ↗</a></div></aside>`}
function sheetStat(label,list){return `<div class="sheet-mini-stat"><span class="sheet-mini-dot ${label.toLowerCase()}"></span><strong>${sheetCount(list)}</strong><span>/ ${list.length}</span><small>${label}</small></div>`}
function renderSheet(kind,arg){
  const [first,subgroup]=String(arg||'').split('/');
  const topic=kind==='topic'?(first==='sorting'?'Sorting':'Arrays'):null;
  const pattern=kind==='pattern'&&first?patterns().find(p=>p===decodeURIComponent(first)):null;
  const key=`${kind}:${arg||''}`;
  if(sheetState.key!==key){Object.assign(sheetState,{key,query:'',difficulty:'All',status:'All'})}
  const groups=topic?sheetGroups(topic,subgroup):[['Matching problems',notes.filter(n=>!pattern||n.pattern===pattern)]];
  const scope=groups.flatMap(([,list])=>list);
  const title=topic?(subgroup?(topic==='Arrays'?`${topic} · ${subgroup[0].toUpperCase()+subgroup.slice(1)}`:`${topic} · Sorting ${subgroup==='1'?'I':'II'}`):topic):pattern||'Patterns';
  const summary=topic?(topic==='Arrays'?'Move from the fundamentals to the harder array patterns, one problem at a time.':'Build a clear picture of how common sorting methods work.'):pattern?'Every note that uses this technique, grouped for focused revision.':'Choose a pattern to explore related problems across the sheet.';
  app.innerHTML=`<div class="sheet-shell">${sheetSidebar(topic,subgroup)}<div class="sheet-content"><div class="sheet-topline"><button class="sheet-menu" type="button" data-sheet-action="open-sidebar" aria-label="Open sheet sections">☰</button><span class="sheet-breadcrumb">DSA Notebook <span>›</span> ${topic?'Topics':'Patterns'} ${subgroup||pattern?`<span>›</span> ${esc(title)}`:''}</span><span class="sheet-top-total">${revised()} / ${notes.length} revised</span></div><div class="sheet-main"><header class="sheet-page-head"><span class="eyebrow">${topic?'Problem sheet':'Pattern index'}</span><h1>${esc(title)}</h1><p>${summary}</p></header><div class="sheet-progress-panel"><div class="sheet-progress-main"><strong>${sheetCount(scope)}</strong><span>of ${scope.length} revised</span></div><div class="sheet-progress-stats">${['Easy','Medium','Hard'].map(d=>sheetStat(d,scope.filter(n=>n.difficulty===d))).join('')}</div><div class="sheet-progress-track"><div style="width:${scope.length?Math.round(sheetCount(scope)/scope.length*100):0}%"></div></div></div>${kind==='pattern'?`<div class="sheet-patterns"><span class="sheet-filter-label">Choose a pattern</span><div class="chip-row">${patterns().map(p=>`<a class="chip ${pattern===p?'active':''}" href="#/patterns/${encodeURIComponent(p)}">${esc(p)}</a>`).join('')}</div></div>`:''}<div class="sheet-controls"><label class="sheet-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.3"/><path d="m16 16 4.3 4.3"/></svg><input id="sheet-query" type="search" value="${esc(sheetState.query)}" placeholder="Search within this ${topic?'topic':'view'}…" aria-label="Search problems in this view"></label><div class="sheet-filter-line"><div class="sheet-segments" role="group" aria-label="Filter by difficulty">${['All','Easy','Medium','Hard'].map(d=>`<button type="button" class="${sheetState.difficulty===d?'active':''}" data-sheet-filter="difficulty" data-value="${d}" aria-pressed="${sheetState.difficulty===d}">${d}</button>`).join('')}</div><div class="sheet-segments" role="group" aria-label="Filter by completion">${['All','Not done','Done'].map(d=>`<button type="button" class="${sheetState.status===d?'active':''}" data-sheet-filter="status" data-value="${d}" aria-pressed="${sheetState.status===d}">${d}</button>`).join('')}</div></div></div><div id="sheet-list" class="sheet-list"></div></div></div></div>`;
  sheetUpdateList(groups);
}
function sheetUpdateList(groups){
  if(!groups){const [kind,arg]=sheetState.key.split(':');const [first,subgroup]=String(arg||'').split('/');const topic=kind==='topic'?(first==='sorting'?'Sorting':'Arrays'):null;const pattern=kind==='pattern'&&first?patterns().find(p=>p===decodeURIComponent(first)):null;groups=topic?sheetGroups(topic,subgroup):[['Matching problems',notes.filter(n=>!pattern||n.pattern===pattern)]]}
  const match=n=>(!sheetState.query||norm(n.title+' '+n.pattern).includes(norm(sheetState.query)))&&(sheetState.difficulty==='All'||n.difficulty===sheetState.difficulty)&&(sheetState.status==='All'||(sheetState.status==='Done'?statusOf(n)==='revised':statusOf(n)!=='revised'));
  const sections=groups.map(([title,list])=>{const visible=list.filter(match);if(!visible.length)return '';return `<section class="sheet-group"><div class="sheet-group-head"><h2>${esc(title)}</h2><span>${sheetCount(list)} / ${list.length} revised</span></div><div class="sheet-rows">${visible.map(sheetRow).join('')}</div></section>`}).join('');
  document.querySelector('#sheet-list').innerHTML=sections||`<div class="empty"><h3>No problems match.</h3><p>Try a different search or filter.</p><button class="pill secondary" type="button" data-sheet-action="reset-filters">Clear filters</button></div>`;
}
document.addEventListener('input',e=>{if(e.target.id==='sheet-query'){sheetState.query=e.target.value;sheetUpdateList()}});
document.addEventListener('change',e=>{const input=e.target.closest('.sheet-check');if(!input)return;const n=notes.find(x=>x.id===input.dataset.id);if(n)setProgress(n,{status:input.checked?'revised':'not-started',lastRevised:input.checked?Date.now():null})});
document.addEventListener('click',e=>{const filterButton=e.target.closest('[data-sheet-filter]');if(filterButton){sheetState[filterButton.dataset.sheetFilter]=filterButton.dataset.value;document.querySelectorAll(`[data-sheet-filter="${filterButton.dataset.sheetFilter}"]`).forEach(b=>{const active=b===filterButton;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});sheetUpdateList();return}const action=e.target.closest('[data-sheet-action]')?.dataset.sheetAction;if(action==='open-sidebar')document.querySelector('#sheet-sidebar')?.classList.add('open');if(action==='close-sidebar')document.querySelector('#sheet-sidebar')?.classList.remove('open');if(action==='reset-filters'){Object.assign(sheetState,{query:'',difficulty:'All',status:'All'});const [kind,arg]=sheetState.key.split(':');renderSheet(kind,arg)}});
